def detect_cycle(values: list[int], pos: int) -> int:
    nodes = []
    for value in values:
        node = _node_chain([value])
        if nodes:
            nodes[-1].nxt = node
        nodes.append(node)
    if not nodes:
        return -1
    if pos >= 0:
        nodes[-1].nxt = nodes[pos]
    slow = fast = nodes[0]
    while fast is not None and fast.nxt is not None:
        slow = slow.nxt
        fast = fast.nxt.nxt
        if slow is fast:
            finder = nodes[0]
            while finder is not slow:
                finder = finder.nxt
                slow = slow.nxt
            return nodes.index(finder)
    return -1

